"use client";

/**
 * Card carousel: a rail of cards on a tilted plane is flicked sideways, coasts
 * on its momentum and settles with one card centred and lifted.
 *
 * Written by Better Design. The rail leans with its speed while it coasts, and
 * the cards either side dim once it stops so the eye lands on the centre.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

const CARD_W = 400;
const CARD_H = 520;
const SPACING = 460;
/** How many cards the flick travels, and the window it coasts through. */
const TRAVEL = 6;
const DRAG_FRAMES = 12;
const COAST_FRAMES = 80;
const LIFT_AT = 78;
/** The rail draws this many cards either side of the ones in view. */
const FIRST = -5;
const LAST = TRAVEL + 5;

/** A shadow ink that stays dark in both modes, so a dark theme never glows. */
const shade = (alpha: number): string => `oklch(0.14 0.01 60 / ${alpha})`;


export interface CardCarouselProps {
  /** Card titles. The rail repeats them, and the flick lands on the seventh card. */
  cards?: string[];
  /** Image paths shown on the cards, matched by position. Unset, each card draws gradient art. */
  pictures?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** Where the rail is centred, in cards, at a frame: a short drag back, then a flick that coasts to rest. */
const railAt = (frame: number): number =>
  -0.18 * easings.out(progress(frame, 0, DRAG_FRAMES)) + (TRAVEL + 0.18) * easings.out(progress(frame, DRAG_FRAMES, COAST_FRAMES));

function Art({ index, theme }: { index: number; theme: VideoTheme }) {
  const hue = shiftHue(theme.primary, ((index * 29) % 120) - 60);
  return (
    <div style={{ position: "absolute", inset: 0, background: `linear-gradient(160deg, ${hue}, ${withAlpha(shiftHue(hue, 40), 0.5)}), ${theme.card}` }}>
      <div style={{ position: "absolute", left: 36, top: 36, width: 120, height: 120, borderRadius: index % 2 ? 60 : 28, background: withAlpha(theme.primaryForeground, 0.32) }} />
      <div style={{ position: "absolute", left: 36, right: 36, bottom: 36, height: 120, borderRadius: 18, background: withAlpha(theme.primaryForeground, 0.18) }} />
    </div>
  );
}

/** A tilted rail of cards flicked sideways, settling with one card centred and lifted. */
export function CardCarousel({
  cards = ["Onboarding", "Dashboard", "Reports", "Settings", "Billing", "Team", "Integrations", "Mobile"],
  pictures = [],
  theme: themeOverride,
  font,
}: CardCarouselProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const list = cards.length > 0 ? cards : ["Your card"];

  const center = railAt(frame);
  const velocity = center - railAt(frame - 1);
  const lift = easings.out(progress(frame, LIFT_AT, 22));
  const enter = easings.out(progress(frame, 0, 12));

  const rail = [];
  for (let k = FIRST; k <= LAST; k++) {
    const index = ((k % list.length) + list.length) % list.length;
    const offset = k - center;
    const near = Math.max(0, 1 - Math.abs(offset));
    const up = near * lift;
    const picture = pictures.length ? pictures[index % pictures.length] : undefined;
    rail.push(
      <div
        key={k}
        style={{
          position: "absolute",
          left: offset * SPACING - CARD_W / 2,
          top: -CARD_H / 2,
          width: CARD_W,
          height: CARD_H,
          borderRadius: theme.radius + 14,
          overflow: "hidden",
          background: theme.card,
          border: `1px solid ${up > 0.5 ? withAlpha(theme.primary, 0.5 * up) : theme.border}`,
          opacity: 1 - 0.45 * (1 - near) * lift,
          transform: `translateZ(${up * 110}px) translateY(${-up * 26}px) skewX(${-velocity * 22}deg)`,
          boxShadow: `0 ${30 + up * 50}px ${60 + up * 60}px -30px ${shade(0.3 + 0.2 * up)}`,
        }}
      >
        <div style={{ position: "relative", height: CARD_H - 112 }}>
          {picture ? <Img src={srcOf(picture)} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Art index={index} theme={theme} />}
        </div>
        <div style={{ height: 112, padding: "0 30px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <span style={{ fontSize: 34, fontWeight: 600, letterSpacing: "-0.025em", color: theme.cardForeground }}>{list[index]}</span>
          <span style={{ fontSize: 24, fontWeight: 500, color: theme.mutedForeground, fontVariantNumeric: "tabular-nums" }}>
            {String(index + 1).padStart(2, "0")}
          </span>
        </div>
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 900px 520px at 50% 55%, ${withAlpha(theme.primary, 0.1 * lift)}, ${withAlpha(theme.primary, 0)} 70%)` }} />
      <AbsoluteFill style={{ perspective: 2200, perspectiveOrigin: "50% 40%", opacity: enter }}>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "52%",
            transformStyle: "preserve-3d",
            transform: `rotateX(14deg) rotateY(-16deg) rotateZ(-3deg) translateY(${(1 - enter) * 40}px)`,
          }}
        >
          {rail}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
